import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import axios from "axios";
import "./Seo.css";

function SEO() {
    const location = useLocation();
    const navigate = useNavigate();

    const { videoURL, localVideoPath } = location.state || {}; // Extract videoURL and localVideoPath from the state
    const [videoData, setVideoData] = useState({ title: "", thumbnail: "" });
    const [seoResults, setSeoResults] = useState(null);
    const [processing, setProcessing] = useState(false);
    const [error, setError] = useState(null);

    // Fetch video metadata
    useEffect(() => {
        const fetchMetadata = async () => {
            if (!videoURL) return;
            try {
                const data = await axios.post(
                    "http://127.0.0.1:8000/api/video-metadata/",
                    { videoURL },
                    { headers: { "Content-Type": "application/json" } }
                );
                setVideoData({
                    title: data.data.title || "No title available",
                    thumbnail: data.data.thumbnail || "https://via.placeholder.com/300x300",
                });
            } catch (err) {
                setError("Failed to fetch video metadata. Please try again.");
            }
        };

        fetchMetadata();
    }, [videoURL]);

    // Handle SEO Processing
    const handleGenerateSEO = async () => {
        setProcessing(true);
        setError(null);

        try {
            const response = await axios.post(
                "http://127.0.0.1:8000/api/seo/",
                {
                    videoURL,
                    localVideoPath,
                },
                { headers: { "Content-Type": "application/json" } }
            );

            // Store results and navigate if needed
            setSeoResults(response.data);
            alert("SEO data processed successfully!");

            // Navigate to SEO Results/Analysis page
            navigate("/SeoResults", { state: { seoData: response.data, videoURL } });
        } catch (err) {
            setError("Failed to process SEO data. Please try again.");
            console.error("Error generating SEO data:", err);
        } finally {
            setProcessing(false);
        }
    };

    return (
        <div className="seo-container">
            <h1>SEO Analysis</h1>

            <div className="video-metadata">
                <h2>Video Details</h2>
                <div className="video-preview">
                    <img
                        src={videoData.thumbnail}
                        alt="Video Thumbnail"
                        className="video-thumbnail"
                    />
                    <h3>{videoData.title}</h3>
                </div>
            </div>

            {error && <p className="error-message">{error}</p>}

            {processing ? (
                <p className="processing-message">Processing SEO data. Please wait...</p>
            ) : (
                <button onClick={handleGenerateSEO} className="seo-generate-btn">
                    Generate SEO Data
                </button>
            )}

            {seoResults && (
                <div className="seo-results">
                    <h2>SEO Results</h2>
                    <p>
                        <strong>Keywords:</strong> {seoResults.keywords?.join(", ") || "N/A"}
                    </p>
                    <p>
                        <strong>Description:</strong> {seoResults.description || "N/A"}
                    </p>
                    <p>
                        <strong>Tags:</strong> {seoResults.tags?.join(", ") || "N/A"}
                    </p>
                </div>
            )}
        </div>
    );
}

export default SEO;
